// ScannerTests.swift
// Part-2 conformance tests: scanners, digest, token estimation, trailer split.
//
// Test strategy:
//   1. Load scanner-vectors-v22.json (generated by Oracle/gen_scanner_vectors.py).
//   2. Load originals and enrichment_trailer from the JSONL beds (Vectors/).
//   3. For each of the 509 oracle rows verify:
//      a. sourceDigest(original)       == source_sha256
//      b. estimateTokens(original)     == original_tokens_est
//      c. splitEnrichment(p23)         == split_enrichment.(body, trailer)
//      d. For each of the 26 named patterns:
//         finditer(pattern:in:)        == matches[name]
//
// JSON format (scanner-vectors-v22.json):
//   root: { version, bed_order, pattern_names, rows: [...] }
//   row:  { bed, drawer_id, source_sha256, original_tokens_est,
//           split_enrichment: {body, trailer},
//           matches: { PATTERN_NAME: [{s,e,g:[full,cap1,...]}, ...] } }
//
// Match format: g[0] = full match text (Python m.group(0), skipped here),
//               g[1+] = capturing groups (Python m.groups()).
// MatchResult.groups stores only capturing groups, so we drop g[0].

import Testing
@testable import ContextDistillLib
import Foundation

// MARK: - Vector model

private struct ScannerVector {
    let drawerID: String
    let bed: String
    let sourceSHA256: String
    let originalTokensEst: Int
    let enrichmentTrailer: String          // from JSONL (absent in JSON)
    let trailerBody: String                // from split_enrichment.body in JSON
    let trailerTrailer: String             // from split_enrichment.trailer in JSON
    let original: String                   // from JSONL
    // name → [(start, end, capturing-groups)]  — g[0] (full match) already dropped
    let patternMatches: [String: [(Int, Int, [String?])]]
}

// MARK: - Vector loading

private func loadScannerVectors() -> [ScannerVector] {
    // ── Step 1: Load JSON skeleton (everything except original text). ──
    guard let url = Bundle.module.url(
        forResource: "scanner-vectors-v22",
        withExtension: "json",
        subdirectory: "Vectors"
    ) else {
        preconditionFailure("Missing scanner-vectors-v22.json in Vectors/")
    }
    let data: Data
    do { data = try Data(contentsOf: url) }
    catch { preconditionFailure("Cannot read scanner-vectors-v22.json: \(error)") }

    guard let root = try? JSONSerialization.jsonObject(with: data) as? [String: Any],
          let rowsAny = root["rows"] as? [[String: Any]]
    else { preconditionFailure("Bad JSON structure in scanner-vectors-v22.json") }

    // ── Step 2: Load originals and enrichment_trailer from JSONL beds. ──
    // drawerID → (original, enrichment_trailer)
    var byDrawerID: [String: (orig: String, trailer: String)] = [:]
    for bed in ["debug7", "sample30", "locomo", "blind200"] {
        guard let bedURL = Bundle.module.url(
            forResource: "\(bed)-intent-span-v22",
            withExtension: "jsonl",
            subdirectory: "Vectors"
        ),
              let raw = try? String(contentsOf: bedURL, encoding: .utf8)
        else { continue }
        for line in raw.components(separatedBy: "\n") {
            let trimmed = line.trimmingCharacters(in: .whitespaces)
            guard !trimmed.isEmpty,
                  let d = trimmed.data(using: .utf8),
                  let obj = try? JSONSerialization.jsonObject(with: d) as? [String: Any],
                  let orig = obj["original"] as? String,
                  let drawer = obj["drawer_id"] as? String
            else { continue }
            let enrTrailer = (obj["enrichment_trailer"] as? String) ?? ""
            byDrawerID[drawer] = (orig: orig, trailer: enrTrailer)
        }
    }

    // ── Step 3: Parse each JSON row into a ScannerVector. ──
    return rowsAny.map { row in
        let drawerID   = (row["drawer_id"]           as? String) ?? "<unknown>"
        let bed        = (row["bed"]                 as? String) ?? "<unknown>"
        let sha256     = (row["source_sha256"]        as? String) ?? ""
        let tokEst     = (row["original_tokens_est"] as? Int)    ?? 0

        // split_enrichment is the oracle output for splitEnrichment(p23).
        let split      = row["split_enrichment"]     as? [String: Any]
        let splitBody  = (split?["body"]             as? String) ?? ""
        let splitTrailer = (split?["trailer"]        as? String) ?? ""

        // matches: { PATTERN_NAME: [{s,e,g:[full,cap1,cap2,...]}, ...] }
        let pm = (row["matches"] as? [String: Any]) ?? [:]
        var parsedMatches: [String: [(Int, Int, [String?])]] = [:]
        for (name, matchesAny) in pm {
            guard let matchArr = matchesAny as? [[String: Any]] else { continue }
            parsedMatches[name] = matchArr.compactMap { m -> (Int, Int, [String?])? in
                guard let s = m["s"] as? Int,
                      let e = m["e"] as? Int
                else { return nil }
                // g[0] = full match (Python m.group(0)) — skip; not in MatchResult.
                // g[1+] = capturing groups (Python m.groups()).
                let gAny = m["g"] as? [Any] ?? []
                let groups: [String?] = gAny.dropFirst().map { g -> String? in
                    if g is NSNull { return nil }
                    return g as? String
                }
                return (s, e, groups)
            }
        }

        let pair = byDrawerID[drawerID]
        return ScannerVector(
            drawerID: drawerID,
            bed: bed,
            sourceSHA256: sha256,
            originalTokensEst: tokEst,
            enrichmentTrailer: pair?.trailer ?? "",
            trailerBody: splitBody,
            trailerTrailer: splitTrailer,
            original: pair?.orig ?? "",
            patternMatches: parsedMatches
        )
    }
}

// MARK: - Scanner assertion helper

/// Asserts that `finditer(pattern:in:)` matches the expected decoded triples.
private func assertPatternMatches(
    _ patternName: String,
    scalars: [Unicode.Scalar],
    expected: [(Int, Int, [String?])],
    drawerID: String
) {
    let actual = finditer(pattern: patternName, in: scalars)

    #expect(
        actual.count == expected.count,
        "Pattern \(patternName) count mismatch for \(drawerID): expected \(expected.count), got \(actual.count)"
    )

    let limit = min(actual.count, expected.count)
    for idx in 0 ..< limit {
        let (es, ee, eg) = expected[idx]
        let am = actual[idx]
        let expStr = fmtMatch(start: es, end: ee, groups: eg)
        let actStr = fmtMatch(start: am.start, end: am.end, groups: am.groups)
        #expect(
            am.start == es && am.end == ee && am.groups == eg,
            "Pattern \(patternName) match[\(idx)] for \(drawerID): expected \(expStr), got \(actStr)"
        )
    }
}

/// Pretty-prints a match triple for failure messages.
private func fmtMatch(start: Int, end: Int, groups: [String?]) -> String {
    let gStr = groups.map { $0.map { "\"\($0)\"" } ?? "nil" }.joined(separator: ", ")
    return "[\(start), \(end), [\(gStr)]]"
}

// MARK: - Digest tests

@Test("sourceDigest matches source_sha256 — debug7 (7 rows)")
func digestConformance_debug7() {
    let vecs = loadScannerVectors()
    for v in vecs.filter({ $0.bed == "debug7" }) {
        let actual = sourceDigest(v.original)
        #expect(actual == v.sourceSHA256,
                "SHA256 mismatch for \(v.drawerID): expected \(v.sourceSHA256), got \(actual)")
    }
}

