// MARK: - Trailer split tests

/// Reconstructs the p23 string (original + optional trailer) that splitEnrichment
/// expects, exactly as gen_scanner_vectors.py does:
///   combined = original + " " + enrichment_trailer   (if non-empty)
///   combined = original                               (if empty)
private func p23(v: ScannerVector) -> String {
    v.enrichmentTrailer.isEmpty ? v.original : v.original + " " + v.enrichmentTrailer
}

@Test("splitEnrichment matches split_enrichment — debug7")
func trailerSplitConformance_debug7() {
    let vecs = loadScannerVectors()
    for v in vecs.filter({ $0.bed == "debug7" }) {
        let (body, trailer) = splitEnrichment(p23(v: v))
        #expect(body == v.trailerBody,
                "body mismatch for \(v.drawerID)")
        #expect(trailer == v.trailerTrailer,
                "trailer mismatch for \(v.drawerID)")
    }
}

@Test("splitEnrichment matches split_enrichment — sample30")
func trailerSplitConformance_sample30() {
    let vecs = loadScannerVectors()
