// MARK: - Scanner conformance tests (per-pattern, per-bed)

/// All 26 pattern names in declaration order (must match Scanners.swift dispatch).
private let allPatternNames: [String] = [
    "TRAILER_RE", "PIPE_SPLIT_RE", "INLINE_NUMBERED_RE", "LIST_MARKER_RE",
    "WORD_RE", "NUMBER_RE", "DATE_RE", "CAPITALIZED_RE",
    "GREETING_PREFIX_RE", "GREETING_ONLY_RE", "DIALOGUE_FILLER_ONLY_RE",
    "REVISION_MARKER_RE", "INITIAL_DRAFT_MARKER_RE", "OPERATIVE_RE",
    "TURN_FILLER_RE", "ASSISTANT_BOILERPLATE_RE", "EMBEDDED_USER_FACT_RE",
    "FENCE_OPEN_RE", "MARKDOWN_HEADING_RE", "BOLD_HEADING_RE",
    "FIELD_LINE_RE", "TABLE_SEPARATOR_RE", "DIAGRAM_RE",
    "POLARITY_ONLY_RE", "TRANSFORM_FOLLOWUP_RE", "QUANTITY_VALUE_RE",
]

/// Runs all 26 pattern scanners against all rows in one bed.
private func runScannerConformance(bed: String) {
    let vecs = loadScannerVectors()
    for v in vecs.filter({ $0.bed == bed }) {
        let scalars = Array(v.original.unicodeScalars)
        for name in allPatternNames {
            let expected = v.patternMatches[name] ?? []
            assertPatternMatches(name, scalars: scalars, expected: expected, drawerID: v.drawerID)
        }
    }
}

@Test("Scanner conformance — debug7 (7 rows × 26 patterns)")
func scannerConformance_debug7() {
    runScannerConformance(bed: "debug7")
}

@Test("Scanner conformance — sample30 (30 rows × 26 patterns)")
func scannerConformance_sample30() {
    runScannerConformance(bed: "sample30")
}

@Test("Scanner conformance — locomo (272 rows × 26 patterns)")
func scannerConformance_locomo() {
    runScannerConformance(bed: "locomo")
}

@Test("Scanner conformance — blind200 (200 rows × 26 patterns)")
func scannerConformance_blind200() {
    runScannerConformance(bed: "blind200")
}

// MARK: - Smoke tests for PythonText helpers

@Test("isPythonWhitespace covers the exact Python isspace() set")
func pythonWhitespaceCoverage() {
    // Use a helper to avoid Swift Testing macro UInt8 overflow on large scalar values.
    func ws(_ v: UInt32) -> Bool { isPythonWhitespace(Unicode.Scalar(v)!) }
    // ASCII whitespace
    #expect(ws(0x09))     // \t
    #expect(ws(0x0A))     // \n
    #expect(ws(0x0B))     // \v
    #expect(ws(0x0C))     // \f
    #expect(ws(0x0D))     // \r
    #expect(ws(0x20))     // SPACE
    #expect(ws(0x85))     // NEL
    #expect(ws(0xA0))     // NO-BREAK SPACE
    #expect(ws(0x3000))   // IDEOGRAPHIC SPACE
    // Non-whitespace
    #expect(!ws(0x21))    // !
    #expect(!ws(0x41))    // A
    #expect(!ws(0x1C))    // FILE SEPARATOR (not whitespace in Python)
}

@Test("pySplit matches Python str.split() semantics")
func pySplitBehaviour() {
    let text = "  hello   world  "
    let scalars = Array(text.unicodeScalars)
    let tokens = pySplit(scalars).map { $0.asString() }
    #expect(tokens == ["hello", "world"])

    let empty = pySplit([]).map { $0.asString() }
    #expect(empty.isEmpty)

    let noWs = Array("abc".unicodeScalars)
    #expect(pySplit(noWs).count == 1)
}

@Test("estimateTokens(empty) returns 0")
func estimateTokensEmpty() {
    #expect(estimateTokens("") == 0)
}

@Test("utf8ByteOffset converts code-point index to UTF-8 byte offset")
func utf8ByteOffsetConversion() {
    // "Aé" = A (1 byte) + é (U+00E9, 2 bytes)
    let scalars = Array("Aé".unicodeScalars)
    let off0 = utf8ByteOffset(forCodePoint: 0, in: scalars)
    let off1 = utf8ByteOffset(forCodePoint: 1, in: scalars)
    let off2 = utf8ByteOffset(forCodePoint: 2, in: scalars)
    #expect(off0 == 0)
    #expect(off1 == 1)
    #expect(off2 == 3)
}
